/** A producer result record. Fields are positional on the wire, in this order. */
export interface ChunkView {
  Id: bigint;
  X: bigint;
  AskedBy: Identity;
}

function readChunkView(reader: TaggedReader): ChunkView {
  const count = reader.array();
  if (count < 3) throw new ProtocolError(`A ChunkView carries 3 fields, not ${count}.`);
  const value: ChunkView = {
    Id: reader.int(),
    X: reader.int(),
    AskedBy: reader.identity(),
  };
  // Fields appended on the server after these bindings were generated are read past.
  for (let extra = 3; extra < count; extra++) reader.skip();
  return value;
}

