/** One typed stub per producer: a read-only server call answered with a value (protocol 3). */
export class MelangeProducers {
  constructor(private readonly client: MelangeClient) {}

  async chunks(minX?: bigint): Promise<(ChunkView | null)[] | null> {
    const reply = await this.client.callProducer("Chunks", encodeArguments(trimDefaults([arg.int64((minX === undefined ? 0n : minX))], [minX], 0)));
    const reader = new TaggedReader(reply.payload);
    const value = (reader.tryNull() ? null : Array.from({ length: reader.array() }, () => (reader.tryNull() ? null : readChunkView(reader))));
    if (!reader.end) throw new ProtocolError("The Chunks result left bytes unread.");
    return value;
  }

  async hang(): Promise<number> {
    const reply = await this.client.callProducer("Hang", encodeArguments([]));
    const reader = new TaggedReader(reply.payload);
    const value = Number(reader.int());
    if (!reader.end) throw new ProtocolError("The Hang result left bytes unread.");
    return value;
  }
}

/** A connected client with this schema's typed tables, reducers, and producers. */
export class MelangeConnection {
  static readonly schemaHash = schemaHash;
  readonly db: MelangeDbView;
  readonly reducers: MelangeReducers;
  readonly producers: MelangeProducers;

  constructor(readonly client: MelangeClient) {
    this.db = new MelangeDbView(new TableCaches(client));
    this.reducers = new MelangeReducers(client);
    this.producers = new MelangeProducers(client);
  }

  /** Who the server says this connection is. Read it; never derive it. */
  get identity(): Identity | null {
    return this.client.identity;
  }
}

void [Identity, ProtocolError, TaggedReader, arg, compareBytes, encodeArguments, encodeKey, trimDefaults];
export type { Arg, ColumnValue, ScheduleAt };
